package main

import "fmt"

// Fungsi yang mengembalikan fungsi (Closure)
// Sering digunakan untuk membuat generator atau middleware
func tokenGenerator() func() string {
	tokenID := 100 // Variabel ini akan "diingat" oleh fungsi di bawahnya

	return func() string {
		tokenID++
		return fmt.Sprintf("TOKEN-%d", tokenID)
	}
}

func main() {
	fmt.Println("=== Anonymous Function ===")
	greeting := func(name string) {
		fmt.Println("Hello,", name)
	}
	greeting("Engineer")

	// Dieksekusi seketika (Immediately Invoked Function)
	func() {
		fmt.Println("Ini fungsi inline yang langsung berjalan!")
	}()

	fmt.Println("\n=== Closures ===")
	genA := tokenGenerator()
	fmt.Println("Sistem A:", genA()) // TOKEN-101
	fmt.Println("Sistem A:", genA()) // TOKEN-102

	// genB memiliki "state" (ingatan) yang berbeda dari genA
	genB := tokenGenerator()
	fmt.Println("Sistem B:", genB()) // TOKEN-101
}
